def longest_capped_run(log, m):
    count = {}
    best = left = 0
    for right, x in enumerate(log):
        count[x] = count.get(x, 0) + 1
        while count[x] > m:
            count[log[left]] -= 1
            left += 1
        best = max(best, right - left + 1)
    return best

